+  await loadCourses(true);
+  rerender();
+}
+function created() {
+  adding.value = false;
+  rerender();
+}
+const reportText = (r) => (!r ? '—' : r.saved ? `saved (v${r.revision})` : r.status === 'complete' ? 'not saved yet' : r.status);
